function overviewEngagementLabel(value: RelationshipScoreValue) {
  switch (value) {
    case 3:
      return "Fully Committed";
    case 2:
      return "Committed";
    case 1:
      return "Seeking";
    case -1:
      return "Crisis Driven";
    case -2:
      return "Resistant";
    case -3:
      return "Hardened";
    case 0:
    default:
      return "Neutral";
  }
}

