  const [focusedCircle, setFocusedCircle] = useState<CircleFocusView | null>(null);
  const isMy3Focused = focusedCircle === "three";
  const isMy12Focused = focusedCircle === "twelve";
  const isMy70Focused = focusedCircle === "seventy";
