function CalendarSyncStatus({
  calendarConnection,
  googleEventCount,
  isSyncingGoogleCalendar,
  onSyncGoogleCalendar,
  workspaceId,
  workspaceSlug,
}: {
  calendarConnection: DosAppCalendarConnection;
  googleEventCount: number;
  isSyncingGoogleCalendar: boolean;
  onSyncGoogleCalendar: () => void;
  workspaceId: string;
  workspaceSlug: string;
}) {
  if (!calendarConnection.connected) {
    return null;
  }

  const needsReconnect = calendarConnectionNeedsReconnect(calendarConnection);
  const lastSyncedLabel = calendarConnection.lastSyncedAt ? `Last synced ${formatTime(calendarConnection.lastSyncedAt)}` : "Calendar events refresh automatically.";

  return (
    <div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-x-2 gap-y-1.5 rounded-[16px] border border-[#DCEBFF] bg-[#F8FBFF] px-3 py-2">
      <span className={`inline-flex min-w-0 items-center gap-1.5 text-xs font-bold ${needsReconnect ? "text-[#1D4ED8]" : "text-[#15803D]"}`}>
        <CheckCircle2 className="h-3.5 w-3.5 shrink-0" aria-hidden="true" strokeWidth={1.9} />
        <span className="truncate">{needsReconnect ? "Reconnect Google Calendar" : "Google Calendar Connected"}</span>
      </span>
      {needsReconnect ? (
        <a
          className="inline-flex min-h-7 shrink-0 items-center justify-center rounded-full border border-[#BFDBFE] bg-white px-2.5 text-[10px] font-bold uppercase tracking-[0.12em] text-[#1D4ED8]"
          href={googleCalendarConnectHref(workspaceId, workspaceSlug)}
          style={{ fontFamily: font.rajdhani }}
        >
          Reconnect
        </a>
      ) : (
        <button
          className="inline-flex min-h-7 shrink-0 items-center justify-center gap-1.5 rounded-full border border-[#BFDBFE] bg-white px-2.5 text-[10px] font-bold uppercase tracking-[0.12em] text-[#1D4ED8] disabled:opacity-60"
          disabled={isSyncingGoogleCalendar}
          onClick={onSyncGoogleCalendar}
          style={{ fontFamily: font.rajdhani }}
          type="button"
        >
          <RefreshCw className={`h-3 w-3 ${isSyncingGoogleCalendar ? "animate-spin" : ""}`} aria-hidden="true" strokeWidth={1.9} />
          Refresh
        </button>
      )}
      <span className="col-span-2 text-xs font-semibold text-[#64748B]">{needsReconnect ? googleCalendarReconnectCopy : lastSyncedLabel}</span>
      {!needsReconnect && googleEventCount === 0 ? (
        <span className="col-span-2 text-xs leading-5 text-[#64748B]">{googleCalendarEmptyStateCopy}</span>
      ) : null}
    </div>
  );
}

function CalendarSourceChip({
  disabled = false,
  label,
  onClick,
  selected,
  tone = "blue",
  variant = "primary",
}: {
  disabled?: boolean;
  label: string;
  onClick: () => void;
  selected: boolean;
  tone?: "blue" | "green" | "muted";
  variant?: "primary" | "secondary";
}) {
  const selectedClasses = variant === "secondary"
    ? "border-[#BFDBFE] bg-[#F8FBFF] text-[#1D4ED8]"
    : tone === "green"
      ? "border-[#86EFAC] bg-[#DCFCE7] text-[#15803D]"
      : tone === "muted"
        ? "border-[#BAE6FD] bg-[#F0F9FF] text-[#0369A1]"
        : "border-[#BFDBFE] bg-[#EBF2FF] text-[#1D4ED8]";
  const idleClasses = variant === "secondary"
    ? "border-[#EAF2FF] bg-white/72 text-[#64748B] hover:border-[#BFDBFE] hover:bg-[#F8FBFF] hover:text-[#1D4ED8]"
    : "border-[#E2E8F0] bg-white text-[#64748B] hover:border-[#BFDBFE] hover:bg-[#F8FBFF] hover:text-[#1D4ED8]";
  const sizeClasses = variant === "secondary"
    ? "min-h-7 max-w-[150px] gap-1 rounded-full px-2.5 text-[9px] tracking-[0.1em]"
    : "min-h-8 max-w-[156px] gap-1.5 rounded-full px-3 text-[10px] tracking-[0.12em]";

  return (
    <button
      aria-pressed={selected}
      className={`inline-flex shrink-0 items-center justify-center border font-black uppercase transition-colors disabled:cursor-not-allowed disabled:opacity-50 ${sizeClasses} ${
        selected
          ? selectedClasses
          : idleClasses
      }`}
      disabled={disabled}
      onClick={onClick}
      style={{ fontFamily: font.rajdhani }}
      type="button"
    >
      <span className="truncate">{label}</span>
    </button>
  );
}

