function MeetingCalendarView({
  calendarConnection,
  calendarDisplaySettings,
  calendarSourceMessage,
  calendarSourcePreferences,
  calendarSyncMessage,
  googleEventCount,
  isSyncingGoogleCalendar,
  items,
  month,
  onChangeMonth,
  onEditMeeting,
  onOpenExternalEvent,
  onEditReminder,
  onToggleCalendarCoreSource,
  onToggleGoogleCalendarSource,
  onLogTable,
  onLogScheduledMeeting,
  onOpenMeeting,
  onSelectDate,
  onSyncGoogleCalendar,
  onToday,
  people,
  recentlyCompletedMeetings,
  savingCalendarSourceId,
  selectedDateKey,
  viewMode,
  onViewModeChange,
  workspaceId,
  workspaceSlug,
}: {
  calendarConnection: DosAppCalendarConnection;
  calendarDisplaySettings: CalendarDisplaySettings;
  calendarSourceMessage: string;
  calendarSourcePreferences: CalendarSourcePreference[];
  calendarSyncMessage: string;
  googleEventCount: number;
  isSyncingGoogleCalendar: boolean;
  items: MeetingCalendarItem[];
  month: Date;
  onChangeMonth: (offset: number) => void;
  onEditMeeting: (meeting: DosAppMeeting) => void;
  onOpenExternalEvent: (eventId: string) => void;
  onEditReminder: (reminderId: string) => void;
  onToggleCalendarCoreSource: (source: CalendarCoreSource) => void;
  onToggleGoogleCalendarSource: (sourceId: string) => void;
  onLogTable: (personIds?: string[], meetingType?: DosAppMeetingType) => void;
  onLogScheduledMeeting: (meeting: DosAppMeeting) => void;
  onOpenMeeting: (meetingId: string) => void;
  onSelectDate: (date: Date) => void;
  onSyncGoogleCalendar: () => void;
  onToday: () => void;
  people: DosAppPerson[];
  recentlyCompletedMeetings: DosAppMeeting[];
  savingCalendarSourceId: string | null;
  selectedDateKey: string;
  viewMode: MeetingCalendarViewMode;
  onViewModeChange: (value: MeetingCalendarViewMode) => void;
  workspaceId: string;
  workspaceSlug: string;
}) {
  const [selectedQuickItemId, setSelectedQuickItemId] = useState<string | null>(null);
  const [locallyCompletedItemIds, setLocallyCompletedItemIds] = useState<string[]>([]);
  const monthStart = startOfCalendarMonth(month);
  const gridStart = new Date(monthStart);
  gridStart.setDate(monthStart.getDate() - monthStart.getDay());
  const selectedDate = dateFromCalendarKey(selectedDateKey);
  const weekStart = startOfCalendarWeek(selectedDate);
  const weekEnd = addCalendarDays(weekStart, 6);
  const weekDays = Array.from({ length: 7 }, (_, index) => addCalendarDays(weekStart, index));
  const googleCalendarConnected = calendarConnection.connected && !calendarConnectionNeedsReconnect(calendarConnection);

  const calendarDays = Array.from({ length: 42 }, (_, index) => {
    const date = new Date(gridStart);
    date.setDate(gridStart.getDate() + index);
    return date;
  });
  const filteredItems = items
    .filter((item) => calendarItemMatchesDisplaySettings(item, calendarDisplaySettings, calendarSourcePreferences))
    .filter((item) => !locallyCompletedItemIds.includes(item.id));
  const nowTime = Date.now();
  const upcomingCardItems = filteredItems
    .filter((item) => dateSortValue(item.date) >= nowTime)
    .slice(0, 12);
  const needsReviewItems = filteredItems
    .filter((item) => dateSortValue(item.date) < nowTime)
    .sort((first, second) => dateSortValue(second.date) - dateSortValue(first.date))
    .slice(0, 8);
  const itemsByDay = filteredItems.reduce((map, item) => {
    const key = calendarDateKeyFromValue(item.date);

    if (!key) {
      return map;
    }

    const dayItems = map.get(key) ?? [];
    dayItems.push(item);
    map.set(key, dayItems);

    return map;
  }, new Map<string, MeetingCalendarItem[]>());
  const selectedQuickItem = selectedQuickItemId ? filteredItems.find((item) => item.id === selectedQuickItemId) ?? null : null;
  const sourceStatusText = calendarSyncMessage
    || (calendarConnectionNeedsReconnect(calendarConnection)
      ? googleCalendarReconnectCopy
      : googleCalendarConnected ? "Google overlays are optional." : "Connect Google to add overlays.");
  const weekItems = filteredItems.filter((item) => {
    const date = parseDisplayDate(item.date);
    const weekEndDay = new Date(weekEnd.getFullYear(), weekEnd.getMonth(), weekEnd.getDate(), 23, 59, 59, 999);

    return Boolean(date && date.getTime() >= weekStart.getTime() && date.getTime() <= weekEndDay.getTime());
  });

  function openQuickItem(item: MeetingCalendarItem) {
    setSelectedQuickItemId(item.id);
    const date = parseDisplayDate(item.date);

    if (date) {
      onSelectDate(date);
    }
  }

  function editQuickItem(item: MeetingCalendarItem) {
    if (item.meeting) {
      onEditMeeting(item.meeting);
      return;
    }

    if (item.reminder) {
      onEditReminder(item.reminder.id);
      return;
    }

    if (item.externalEvent) {
      onOpenExternalEvent(item.externalEvent.id);
    }
  }

  function logQuickItem(item: MeetingCalendarItem) {
    if (item.meeting) {
      onLogScheduledMeeting(item.meeting);
      return;
    }

    const personIds = item.personId ? [item.personId] : [];

    onLogTable(personIds);
  }

  function handleQuickPrimaryAction(item: MeetingCalendarItem) {
    if (item.kind === "meeting") {
      logQuickItem(item);
      return;
    }

    if (item.kind === "google") {
      editQuickItem(item);
      return;
    }

    setLocallyCompletedItemIds((current) => current.includes(item.id) ? current : [...current, item.id]);
    setSelectedQuickItemId(null);
  }

  function handleNeedsReviewPrimaryAction(item: MeetingCalendarItem) {
    if (item.kind === "meeting") {
      logQuickItem(item);
      return;
    }

    if (item.kind === "google") {
      editQuickItem(item);
      return;
    }

    setLocallyCompletedItemIds((current) => current.includes(item.id) ? current : [...current, item.id]);
    setSelectedQuickItemId(null);
  }

  function handleNeedsReviewSecondaryAction(item: MeetingCalendarItem) {
    if (item.kind === "google") {
      setLocallyCompletedItemIds((current) => current.includes(item.id) ? current : [...current, item.id]);
      setSelectedQuickItemId(null);
      return;
    }

    if (item.meeting || item.reminder) {
      editQuickItem(item);
      return;
    }

    setLocallyCompletedItemIds((current) => current.includes(item.id) ? current : [...current, item.id]);
    setSelectedQuickItemId(null);
  }

  function shiftCalendar(offset: number) {
    if (viewMode === "week") {
      onSelectDate(addCalendarDays(selectedDate, offset * 7));
      return;
    }

    onChangeMonth(offset);
  }

  function weekEventStyle(item: MeetingCalendarItem) {
    const date = parseDisplayDate(item.date) ?? selectedDate;
    const dayStart = startOfDisplayDay(date.toISOString()) ?? weekStart;
    const dayIndex = Math.max(0, Math.min(6, Math.round((dayStart.getTime() - weekStart.getTime()) / (24 * 60 * 60 * 1000))));
    const minuteOfDay = Math.max(8 * 60, Math.min(20 * 60, calendarItemMinuteOfDay(item)));
    const rowStart = Math.floor((minuteOfDay - 8 * 60) / 60) + 2;
    const span = Math.max(1, Math.min(3, Math.ceil(calendarItemDurationMinutes(item) / 60)));
    const marginTop = Math.round(((minuteOfDay % 60) / 60) * 28);

    return {
      gridColumn: `${dayIndex + 2}`,
      gridRow: `${rowStart} / span ${span}`,
      marginTop: `${marginTop}px`,
    };
  }

  return (
    <section className="grid min-w-0 max-w-full gap-3">
      <CalendarNeedsReviewSection
        items={needsReviewItems}
        onOpen={openQuickItem}
        onPrimaryAction={handleNeedsReviewPrimaryAction}
        onSecondaryAction={handleNeedsReviewSecondaryAction}
      />

      {selectedQuickItem ? (
        <CalendarQuickView
          item={selectedQuickItem}
          onClose={() => setSelectedQuickItemId(null)}
          onEdit={() => editQuickItem(selectedQuickItem)}
          onPrimaryAction={() => handleQuickPrimaryAction(selectedQuickItem)}
        />
      ) : null}

      <div className="w-full max-w-full overflow-hidden rounded-[28px] border border-[#DCEBFF] bg-white shadow-[0_18px_48px_rgba(37,99,235,0.07)] md:rounded-[26px] md:bg-white/92 md:backdrop-blur">
        <header className="grid gap-3 border-b border-[#EFF6FF] px-3 py-3">
          <div className="flex min-w-0 items-center justify-between gap-2">
            <button
              aria-label={viewMode === "week" ? "Previous week" : "Previous month"}
              className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-[#2563EB] transition-colors hover:bg-[#EBF2FF]"
              onClick={() => shiftCalendar(-1)}
              type="button"
            >
              <ArrowLeft className="h-4 w-4" aria-hidden="true" strokeWidth={1.9} />
            </button>
            <div className="min-w-0 text-center">
              <h2 className="truncate text-base font-black leading-tight text-[#0F172A]" style={{ fontFamily: font.oswald }}>
                {viewMode === "week" ? calendarWeekRangeLabel(weekStart) : calendarMonthLabel(month)}
              </h2>
              <button className="mt-1 text-[10px] font-bold uppercase tracking-[0.14em] text-[#2563EB]" onClick={onToday} style={{ fontFamily: font.rajdhani }} type="button">
                Today
              </button>
            </div>
            <button
              aria-label={viewMode === "week" ? "Next week" : "Next month"}
              className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-[#2563EB] transition-colors hover:bg-[#EBF2FF]"
              onClick={() => shiftCalendar(1)}
              type="button"
            >
              <ChevronRight className="h-4 w-4" aria-hidden="true" strokeWidth={1.9} />
            </button>
          </div>
          <div className="grid gap-2">
            <SegmentedTabs onChange={onViewModeChange} options={meetingCalendarViewTabs} value={viewMode} />
            <CalendarSourceControls
              calendarConnection={calendarConnection}
              displaySettings={calendarDisplaySettings}
              onToggleCoreSource={onToggleCalendarCoreSource}
              onToggleGoogleSource={onToggleGoogleCalendarSource}
              savingSourceId={savingCalendarSourceId}
              sourcePreferences={calendarSourcePreferences}
            />
            {calendarConnectionNeedsReconnect(calendarConnection) ? (
              <div className="flex items-center justify-between gap-2 rounded-[16px] border border-[#BFDBFE] bg-[#EBF2FF] px-3 py-2">
                <span className="min-w-0 text-xs font-bold leading-5 text-[#1D4ED8]">{googleCalendarReconnectCopy}</span>
                <a
                  className="inline-flex min-h-7 shrink-0 items-center justify-center rounded-full border border-[#BFDBFE] bg-white px-2.5 text-[10px] font-bold uppercase tracking-[0.12em] text-[#1D4ED8]"
                  href={googleCalendarConnectHref(workspaceId, workspaceSlug)}
                  style={{ fontFamily: font.rajdhani }}
                >
                  Reconnect
                </a>
              </div>
            ) : null}
          </div>
        </header>

        {viewMode === "month" ? (
          <div className="px-2.5 pb-3 pt-2">
            <div className="grid grid-cols-7 gap-1 pb-1.5">
              {["S", "M", "T", "W", "T", "F", "S"].map((day, index) => (
                <div className="text-center text-[9px] font-bold uppercase tracking-[0.12em] text-[#94A3B8]" key={`${day}-${index}`} style={{ fontFamily: font.rajdhani }}>
                  {day}
                </div>
              ))}
            </div>
            <div className="grid grid-cols-7 gap-1">
              {calendarDays.map((date) => {
                const key = calendarDateKey(date);
                const dayItems = itemsByDay.get(key) ?? [];
                const isSelected = key === selectedDateKey;
                const isOutsideMonth = !isSameCalendarMonth(date, month);
                const isToday = key === todayDateValue();

                return (
                  <button
                    aria-label={new Intl.DateTimeFormat("en-US", { dateStyle: "full" }).format(date)}
                    aria-pressed={isSelected}
                    className={`min-h-[48px] rounded-[16px] px-1.5 py-1.5 text-left transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-[#2563EB]/30 max-[350px]:min-h-[44px] max-[350px]:rounded-[14px] md:min-h-[68px] ${
                      isSelected
                        ? "bg-[#2563EB] text-white shadow-[0_10px_24px_rgba(37,99,235,0.22)]"
                        : isToday
                          ? "bg-[#EBF2FF] text-[#1D4ED8] ring-1 ring-[#BFDBFE]"
                          : "bg-[#F8FAFC] text-[#0F172A] hover:bg-[#EBF2FF]"
                    } ${isOutsideMonth && !isSelected ? "opacity-45" : ""}`}
                    key={key}
                    onClick={() => {
                      onSelectDate(date);
                      if (dayItems[0]) {
                        openQuickItem(dayItems[0]);
                      }
                    }}
                    type="button"
                  >
                    <span className="block text-center text-xs font-bold leading-none max-[350px]:text-[11px]">{date.getDate()}</span>
                    {dayItems.length ? (
                      <span className="mt-2 flex min-h-1.5 items-center justify-center gap-0.5">
                        {dayItems.slice(0, 3).map((item) => (
                          <span className={`h-1.5 w-1.5 rounded-full ${isSelected ? "bg-white" : calendarItemTone(item.kind).dot}`} key={item.id} />
                        ))}
                        {dayItems.length > 3 ? <span className={`text-[8px] font-bold leading-none ${isSelected ? "text-white" : "text-[#64748B]"}`}>+{dayItems.length - 3}</span> : null}
                      </span>
                    ) : null}
                  </button>
                );
              })}
            </div>
          </div>
        ) : (
          <div className="p-2.5">
            <div className="grid overflow-hidden rounded-[22px] border border-[#EAF2FF] bg-white" style={{ gridTemplateColumns: "42px repeat(7, minmax(0, 1fr))" }}>
              <div className="border-b border-r border-[#EFF6FF] bg-[#F8FBFF]" />
              {weekDays.map((day) => {
                const key = calendarDateKey(day);
                const isToday = key === todayDateValue();

                return (
                  <button
                    className={`min-w-0 border-b border-r border-[#EFF6FF] px-1 py-2 text-center last:border-r-0 ${isToday ? "bg-[#EBF2FF]" : "bg-[#F8FBFF]"}`}
                    key={key}
                    onClick={() => onSelectDate(day)}
                    type="button"
                  >
                    <span className="block text-[9px] font-bold uppercase tracking-[0.1em] text-[#64748B]" style={{ fontFamily: font.rajdhani }}>
                      {new Intl.DateTimeFormat("en-US", { weekday: "short" }).format(day)}
                    </span>
                    <span className={`mt-1 inline-flex h-7 w-7 items-center justify-center rounded-full text-xs font-black ${isToday ? "bg-[#2563EB] text-white" : "text-[#0F172A]"}`}>
                      {day.getDate()}
                    </span>
                  </button>
                );
              })}
              {meetingCalendarWeekHours.map((hour, hourIndex) => {
                const gridRow = String(hourIndex + 2);

                return (
                  <div className="contents" key={hour}>
                    <div className="border-r border-t border-[#EFF6FF] bg-white px-1.5 py-2 text-left text-[9px] font-bold text-[#94A3B8]" style={{ fontFamily: font.rajdhani, gridColumn: "1", gridRow }}>
                      {calendarWeekHourLabel(hour)}
                    </div>
                    {weekDays.map((day, dayIndex) => (
                      <div
                        className={`min-h-[52px] border-t border-[#EFF6FF] bg-white ${dayIndex === weekDays.length - 1 ? "" : "border-r"}`}
                        key={`${calendarDateKey(day)}-${hour}`}
                        style={{ gridColumn: String(dayIndex + 2), gridRow }}
                      />
                    ))}
                  </div>
                );
              })}
              {weekItems.map((item) => {
                const tone = calendarItemTone(item.kind);

                return (
                  <button
                    className={`z-10 m-1 min-w-0 rounded-[14px] border px-1.5 py-1 text-left shadow-[0_8px_18px_rgba(37,99,235,0.08)] ${tone.bg} ${tone.text}`}
                    key={`week-${item.id}`}
                    onClick={() => openQuickItem(item)}
                    style={weekEventStyle(item)}
                    type="button"
                  >
                    <span className="block truncate text-[10px] font-black leading-4 sm:text-xs">{item.title}</span>
                    <span className="block truncate text-[9px] font-bold leading-3 opacity-80 sm:text-[10px]">{formatTime(item.date) || calendarItemSourceLabel(item)}</span>
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>

      <CalendarUpcomingSection
        items={upcomingCardItems}
        onOpen={openQuickItem}
        selectedItemId={selectedQuickItemId}
      />

      <RecentlyCompletedTables
        meetings={recentlyCompletedMeetings}
        onOpenMeeting={onOpenMeeting}
        people={people}
      />

      <details className="hidden rounded-[22px] border border-[#DCEBFF] bg-white p-3 shadow-[0_10px_24px_rgba(37,99,235,0.045)] md:block">
        <summary className="flex cursor-pointer list-none items-center justify-between gap-3 text-sm font-black text-[#0F172A] [&::-webkit-details-marker]:hidden">
          <span>Sources</span>
          <span className="text-xs font-semibold text-[#64748B]">{sourceStatusText}</span>
        </summary>
        <div className="mt-3 grid gap-3">
          <CalendarSourceControls
            calendarConnection={calendarConnection}
            displaySettings={calendarDisplaySettings}
            message={calendarSourceMessage}
            onToggleCoreSource={onToggleCalendarCoreSource}
            onToggleGoogleSource={onToggleGoogleCalendarSource}
            savingSourceId={savingCalendarSourceId}
            showMessage
            sourcePreferences={calendarSourcePreferences}
          />
          <CalendarSyncStatus
            calendarConnection={calendarConnection}
            googleEventCount={googleEventCount}
            isSyncingGoogleCalendar={isSyncingGoogleCalendar}
            onSyncGoogleCalendar={onSyncGoogleCalendar}
            workspaceId={workspaceId}
            workspaceSlug={workspaceSlug}
          />
          <p className="text-xs leading-5 text-[#64748B]">Source badges stay visible on each event so the calendar stays focused on what is next.</p>
        </div>
      </details>
    </section>
  );
}

function GoogleCalendarEventDetailSheet({
  event,
  isAdding,
  onAddToDos,
  onClose,
}: {
  event: DosAppExternalCalendarEvent;
  isAdding: boolean;
  onAddToDos: () => void;
  onClose: () => void;
}) {
  const alreadyAdded = Boolean(event.importedMeetingId);

  return (
    <MobileBottomSheet
      badge={<span className="rounded-full border border-[#BFDBFE] bg-[#EBF2FF] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.12em] text-[#1D4ED8]" style={{ fontFamily: font.rajdhani }}>Google</span>}
      footer={(
        <div className="grid gap-2">
          <button
            className="min-h-11 rounded-full bg-[linear-gradient(135deg,#2563EB_0%,#1D4ED8_100%)] px-4 text-sm font-bold text-white shadow-[0_12px_26px_rgba(37,99,235,0.22)] disabled:opacity-60"
            disabled={alreadyAdded || isAdding}
            onClick={onAddToDos}
            type="button"
          >
            {alreadyAdded ? "Already added to DOS" : isAdding ? "Adding..." : "Add to DOS"}
          </button>
          {event.htmlLink ? (
            <a className="inline-flex min-h-10 items-center justify-center gap-2 rounded-full border border-[#E2E8F0] bg-white px-4 text-sm font-bold text-[#0F172A]" href={event.htmlLink} rel="noreferrer" target="_blank">
              Open in Google
              <ExternalLink className="h-3.5 w-3.5" aria-hidden="true" strokeWidth={1.9} />
            </a>
          ) : null}
        </div>
      )}
      onClose={onClose}
      subtitle={formatExternalCalendarEventTimeRange(event)}
      title={googleCalendarEventTitle(event)}
    >
      <div className="grid gap-3">
        <div className="rounded-[22px] border border-[#EAF2FF] bg-[#F8FAFC] p-3">
          <p className="text-[10px] font-bold uppercase tracking-[0.12em] text-[#64748B]" style={{ fontFamily: font.rajdhani }}>Source</p>
          <p className="mt-1 text-sm font-semibold text-[#0F172A]">{googleCalendarSourceMetadata(event)}</p>
        </div>
        {event.location ? (
          <div className="rounded-[22px] border border-[#EAF2FF] bg-white p-3">
            <p className="text-[10px] font-bold uppercase tracking-[0.12em] text-[#64748B]" style={{ fontFamily: font.rajdhani }}>Location</p>
            <p className="mt-1 text-sm leading-5 text-[#334155]">{event.location}</p>
          </div>
        ) : null}
        {event.description ? (
          <div className="rounded-[22px] border border-[#EAF2FF] bg-white p-3">
            <p className="text-[10px] font-bold uppercase tracking-[0.12em] text-[#64748B]" style={{ fontFamily: font.rajdhani }}>Details</p>
            <p className="mt-1 line-clamp-5 whitespace-pre-line text-sm leading-5 text-[#334155]">{event.description}</p>
          </div>
        ) : null}
      </div>
    </MobileBottomSheet>
  );
}

function CompactOptionSelect({
  label,
  onChange,
  options,
  value,
}: {
  label: string;
  onChange: (value: string) => void;
  options: ReadonlyArray<{ helper?: string; label: string; value: string }>;
  value: string;
}) {
  const [isOpen, setIsOpen] = useState(false);
  const selectedOption = options.find((option) => option.value === value) ?? options[0];

  return (
    <div
      className="relative"
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
          setIsOpen(false);
        }
      }}
    >
      <FieldLabel>{label}</FieldLabel>
      <button
        aria-expanded={isOpen}
        className={`mt-2 flex min-h-12 w-full items-center justify-between gap-3 rounded-2xl border bg-white px-4 text-left text-sm transition-colors ${
          isOpen ? "border-[#2563EB] shadow-[0_10px_24px_rgba(37,99,235,0.12)]" : "border-[#E2E8F0] hover:border-[#BFDBFE]"
        }`}
        onClick={() => setIsOpen((current) => !current)}
        type="button"
      >
        <span className="min-w-0 flex-1 truncate font-semibold text-[#0F172A]">{selectedOption?.label ?? "Select"}</span>
        <ChevronRight className={`h-4 w-4 shrink-0 text-[#94A3B8] transition-transform ${isOpen ? "-rotate-90" : "rotate-90"}`} aria-hidden="true" strokeWidth={1.8} />
      </button>
      {isOpen ? (
        <div className="absolute left-0 right-0 z-30 mt-1 overflow-hidden rounded-2xl border border-[#E2E8F0] bg-white p-1.5 shadow-[0_18px_45px_rgba(42,37,29,0.14)]">
          {options.map((option) => {
            const selected = option.value === selectedOption?.value;

            return (
              <button
                aria-pressed={selected}
                className={`flex min-h-10 w-full items-center justify-between gap-3 rounded-xl px-3 text-left text-sm transition-colors ${
                  selected ? "bg-[#EBF2FF] text-[#1D4ED8]" : "text-[#0F172A] hover:bg-[#F1F5F9]"
                }`}
                key={option.value}
                onClick={() => {
                  onChange(option.value);
                  setIsOpen(false);
                }}
                type="button"
              >
                <span className="min-w-0 flex-1 truncate font-semibold">{option.label}</span>
                {option.helper ? <span className="shrink-0 text-[11px] font-medium text-[#94A3B8]">{option.helper}</span> : null}
              </button>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

function FormOptionSelect({
  defaultValue = "",
  label,
  name,
  options,
}: {
  defaultValue?: string;
  label: string;
  name: string;
  options: ReadonlyArray<{ helper?: string; label: string; value: string }>;
}) {
  const [value, setValue] = useState(defaultValue);

  return (
    <>
      <input name={name} type="hidden" value={value} />
      <CompactOptionSelect label={label} onChange={setValue} options={options} value={value} />
    </>
  );
}

function MeetingContextPicker({
  onChange,
  value,
}: {
  onChange: (value: DosAppMeetingType) => void;
  value: DosAppMeetingType;
}) {
  return (
    <CompactOptionSelect
      label="Table Context"
      onChange={(nextValue) => onChange(nextValue as DosAppMeetingType)}
      options={meetingTypeOptions.map((option) => ({ label: option.label, value: option.value }))}
      value={value}
    />
  );
}

function ConversationFlowPicker({
  allowConversationFlows,
  onChange,
  value,
}: {
  allowConversationFlows: boolean;
  onChange: (value: DosConversationFlowKey) => void;
  value: DosConversationFlowKey;
}) {
  const options = allowConversationFlows
    ? conversationFlowOptions
    : conversationFlowOptions.filter((option) => option.value === "none");

  return (
    <CompactOptionSelect
      label="Conversation Flow"
      onChange={(nextValue) => onChange(nextValue as DosConversationFlowKey)}
      options={options}
      value={(options.find((option) => option.value === value) ?? options[0])?.value ?? "none"}
    />
  );
}

function responseAsNumber(value: DosConversationResponseValue | undefined) {
  return typeof value === "number" ? value : undefined;
}

function responseAsString(value: DosConversationResponseValue | undefined) {
  return typeof value === "string" ? value : "";
}

function responseAsStringArray(value: DosConversationResponseValue | undefined) {
  return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : [];
}

function questionResponseLabel(question: DosConversationQuestion, value: DosConversationResponseValue | undefined) {
  if (question.kind === "rating") {
    const rating = responseAsNumber(value);

    return rating ? `${rating} · ${relationshipWithJesusTemperature(rating)}` : "Skipped";
  }

  if (question.kind === "text" || question.kind === "notes") {
    return responseAsString(value) || "No notes";
  }

  return answerLabel(value as DosConversationAnswer | undefined);
}

function conversationFlowPreviewPrompts(flow: NonNullable<ReturnType<typeof getConversationFlowDefinition>>) {
  return flow.sections
    .flatMap((section) => section.questions)
    .map((question) => question.prompt ?? question.label)
    .slice(0, 3);
}

function ConversationFlowExperience({
  flowKey,
  onResponseChange,
  onToggleFollowUpAction,
  recommendedResources,
  responses,
}: {
  flowKey: DosConversationFlowKey;
  onResponseChange: (questionId: string, value: DosConversationResponseValue | undefined) => void;
  onToggleFollowUpAction: (actionId: string) => void;
  recommendedResources: DosRecommendedResource[];
  responses: DosConversationResponses;
}) {
  const flow = getConversationFlowDefinition(flowKey);
  const temperature = flowKey === "kitchen_table_gospel"
    ? relationshipWithJesusTemperature(responseAsNumber(responses.relationshipWithJesus))
    : null;
  const selectedFollowUpActions = responseAsStringArray(responses.followUpActions);

  if (!flow) {
    return null;
  }

  const guideResource = dosTableTeachingResources.find((resource) => resource.title === flow.title) ?? null;
  const previewPrompts = conversationFlowPreviewPrompts(flow);

  return (
    <section className="grid gap-3 rounded-[20px] border border-[#D6E4F7] bg-white p-3">
      <div>
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <p className="text-[10px] font-bold uppercase tracking-[0.14em] text-[#2563EB]" style={{ fontFamily: font.rajdhani }}>
              Conversation Flow
            </p>
            <p className="mt-1 text-sm font-black leading-5 text-[#0F172A]">{flow.title}</p>
            <p className="mt-1 text-xs leading-5 text-[#64748B]">{flow.description}</p>
          </div>
          {temperature ? (
            <span className="shrink-0 rounded-full border border-[#BFDBFE] bg-[#EBF2FF] px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.12em] text-[#1D4ED8]" style={{ fontFamily: font.rajdhani }}>
              {temperature}
            </span>
          ) : null}
        </div>

        {previewPrompts.length ? (
          <div className="mt-3 grid gap-1.5">
            {previewPrompts.map((prompt, index) => (
              <div className="flex gap-2 rounded-2xl border border-[#EAF2FF] bg-white p-2.5 text-xs leading-5 text-[#475569]" key={`${flow.id}-prompt-${index}`}>
                <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[#EBF2FF] text-[10px] font-black text-[#1D4ED8]">
                  {index + 1}
                </span>
                <span>{prompt}</span>
              </div>
            ))}
          </div>
        ) : null}

        {guideResource || recommendedResources.length ? (
          <div className="mt-3 flex flex-wrap gap-1.5">
            {guideResource ? (
              <a
                className="inline-flex min-h-8 items-center gap-1.5 rounded-full border border-[#BFDBFE] bg-[#EBF2FF] px-3 text-xs font-bold text-[#1D4ED8]"
                href={guideResource.href}
                rel="noopener noreferrer"
                target="_blank"
              >
                <BookOpen className="h-3.5 w-3.5" aria-hidden="true" strokeWidth={1.9} />
                Open guide
              </a>
            ) : null}
            {recommendedResources.slice(0, 3).map((resource) => (
              <span className="inline-flex min-h-8 items-center rounded-full border border-[#E2E8F0] bg-white px-3 text-xs font-semibold text-[#0F172A]" key={resource.id}>
                {resource.title}
              </span>
            ))}
          </div>
        ) : null}
      </div>

      <details className="group rounded-[20px] border border-[#D6E4F7] bg-white p-3">
        <summary className="flex cursor-pointer list-none items-center justify-between gap-3 text-sm font-bold text-[#0F172A] [&::-webkit-details-marker]:hidden">
          <span>Capture guided responses</span>
          <ChevronRight className="h-4 w-4 shrink-0 text-[#94A3B8] transition-transform group-open:rotate-90" aria-hidden="true" strokeWidth={1.9} />
        </summary>
        <div className="mt-3 grid gap-3">
          {flow.sections.map((section) => (
            <div className="grid gap-2" key={section.id}>
              <div>
                <p className="text-[10px] font-bold uppercase tracking-[0.14em] text-[#94A3B8]" style={{ fontFamily: font.rajdhani }}>
                  {section.title}
                </p>
                {section.description ? <p className="mt-0.5 text-xs leading-5 text-[#64748B]">{section.description}</p> : null}
              </div>
              {section.questions.map((question) => (
                <ConversationQuestionCard
                  key={question.id}
                  onResponseChange={onResponseChange}
                  question={question}
                  value={responses[question.id]}
                />
              ))}
            </div>
          ))}

          {flow.closingPrompt || flow.gospelInvitation ? (
            <div className="rounded-2xl border border-[#BFDBFE] bg-[#EBF2FF] p-3">
              <p className="text-[10px] font-bold uppercase tracking-[0.14em] text-[#1D4ED8]" style={{ fontFamily: font.rajdhani }}>
                Gospel Invitation
              </p>
              {flow.closingPrompt ? <p className="mt-2 text-sm font-semibold leading-5 text-[#0F172A]">{flow.closingPrompt}</p> : null}
              {flow.gospelInvitation ? <p className="mt-1 text-xs leading-5 text-[#64748B]">{flow.gospelInvitation}</p> : null}
            </div>
          ) : null}

          {flow.followUpActions?.length ? (
            <div className="rounded-2xl border border-[#EAF2FF] bg-white p-2.5">
              <p className="text-sm font-semibold text-[#0F172A]">Follow-up</p>
              <div className="mt-2 flex flex-wrap gap-1.5">
                {flow.followUpActions.map((action) => {
                  const selected = selectedFollowUpActions.includes(action.id);

                  return (
                    <button
                      aria-pressed={selected}
                      className={`min-h-8 rounded-full border px-3 text-xs font-bold ${
                        selected ? "border-[#2563EB] bg-[#EBF2FF] text-[#1D4ED8]" : "border-[#E2E8F0] bg-white text-[#0F172A]"
                      }`}
                      key={action.id}
                      onClick={() => onToggleFollowUpAction(action.id)}
                      type="button"
                    >
                      {action.label}
                    </button>
                  );
                })}
              </div>
            </div>
          ) : null}
        </div>
      </details>
    </section>
  );
}

function ConversationQuestionCard({
  onResponseChange,
  question,
  value,
}: {
  onResponseChange: (questionId: string, value: DosConversationResponseValue | undefined) => void;
  question: DosConversationQuestion;
  value: DosConversationResponseValue | undefined;
}) {
  if (question.kind === "rating") {
    const ratingValue = responseAsNumber(value);
    const scaleMin = question.scale?.min ?? 1;
    const scaleMax = question.scale?.max ?? 10;

    return (
      <div className="rounded-2xl border border-[#EAF2FF] bg-white p-2.5">
        <p className="text-sm font-semibold text-[#0F172A]">{question.label}</p>
        <div className="mt-2 grid grid-cols-5 gap-1.5">
          {Array.from({ length: scaleMax - scaleMin + 1 }, (_, index) => scaleMin + index).map((rating) => {
            const selected = ratingValue === rating;

            return (
              <button
                aria-pressed={selected}
                className={`min-h-8 rounded-xl border text-xs font-bold ${
                  selected ? "border-[#2563EB] bg-[#2563EB] text-white" : "border-[#E2E8F0] bg-white text-[#0F172A]"
                }`}
                key={rating}
                onClick={() => onResponseChange(question.id, selected ? undefined : rating)}
                type="button"
              >
                {rating}
              </button>
            );
          })}
        </div>
        <p className="mt-2 text-[11px] leading-4 text-[#64748B]">1-3 Cold · 4-7 Lukewarm · 8-10 Hot</p>
      </div>
    );
  }

  if (question.kind === "text" || question.kind === "notes") {
    return (
      <label className="block rounded-2xl border border-[#EAF2FF] bg-white p-2.5">
        <span className="text-sm font-semibold text-[#0F172A]">{question.label}</span>
        <VoiceTextarea
          className={`${FieldInputClass()} mt-2 min-h-20 bg-white py-3`}
          onChange={(event) => onResponseChange(question.id, event.target.value)}
          placeholder={question.placeholder}
          value={responseAsString(value)}
        />
      </label>
    );
  }

  const answer = value as DosConversationAnswer | undefined;
  const options = question.kind === "yes_no_unsure" ? conversationUnsureAnswerOptions : conversationYesNoOptions;

  return (
    <div className="rounded-2xl border border-[#EAF2FF] bg-white p-2.5">
      <p className="text-sm font-semibold leading-5 text-[#0F172A]">{question.label}</p>
      {question.scriptureRefs?.length ? (
        <p className="mt-1 text-[11px] font-semibold uppercase tracking-[0.08em] text-[#94A3B8]" style={{ fontFamily: font.rajdhani }}>
          {question.scriptureRefs.join(" · ")}
        </p>
      ) : null}
      {question.prompt ? <p className="mt-1 text-xs leading-5 text-[#64748B]">{question.prompt}</p> : null}
      <div className="mt-2 grid grid-cols-3 gap-1.5">
        {options.map((option) => {
          const selected = answer === option.value;

          return (
            <button
              aria-pressed={selected}
              className={`min-h-8 rounded-xl border text-xs font-bold ${
                selected ? "border-[#2563EB] bg-[#EBF2FF] text-[#1D4ED8]" : "border-[#E2E8F0] bg-white text-[#0F172A]"
              }`}
              key={option.value}
              onClick={() => onResponseChange(question.id, selected ? undefined : option.value)}
              type="button"
            >
              {option.label}
            </button>
          );
        })}
      </div>
    </div>
  );
}

function MeetingPeopleSelector({
  allPeople,
  disabledPersonIds = [],
  isCreatingPerson = false,
  onCreatePerson,
  onQueryChange,
  onToggle,
  people,
  placeholder = "Search your field",
  query,
  removeLabel = "from table",
  selectedPersonIds,
}: {
  allPeople: DosAppPerson[];
  disabledPersonIds?: string[];
  isCreatingPerson?: boolean;
  onCreatePerson?: (name: string) => Promise<void>;
  onQueryChange: (value: string) => void;
  onToggle: (personId: string) => void;
  people: DosAppPerson[];
  placeholder?: string;
  query: string;
  removeLabel?: string;
  selectedPersonIds: string[];
}) {
  const selectedPeople = selectedPersonIds
    .map((personId) => allPeople.find((person) => person.id === personId))
    .filter((person): person is DosAppPerson => Boolean(person));
  const visiblePeople = people.filter((person) => !selectedPersonIds.includes(person.id) && !disabledPersonIds.includes(person.id));
  const hasSearch = query.trim().length > 0;
  const quickAddName = query.trim().replace(/\s+/g, " ");
  const canQuickAdd = Boolean(onCreatePerson && hasSearch && quickAddName && visiblePeople.length === 0);

  return (
    <div className="grid gap-2">
      {selectedPeople.length ? (
        <div className="flex flex-wrap gap-1.5">
          {selectedPeople.map((person, index) => (
            <button
              aria-label={`Remove ${person.name} ${removeLabel}`}
              className="inline-flex h-7 max-w-full items-center gap-1 rounded-full border border-[#BFDBFE] bg-[#EBF2FF] pl-1 pr-2 text-[11px] font-semibold text-[#0F172A] transition-colors hover:border-[#2563EB]"
              key={person.id}
              onClick={() => onToggle(person.id)}
              type="button"
            >
              <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-[8px] font-bold ${avatarTone(index)}`}>
                {initials(person.name)}
              </span>
              <span className="max-w-[9rem] truncate">{person.name}</span>
              <span className="ml-0.5 text-[13px] leading-none text-[#1D4ED8]" aria-hidden="true">
                &times;
              </span>
            </button>
          ))}
        </div>
      ) : null}

      <div className="relative">
        <span className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-[#94A3B8]">
          <Icon name="search" size={14} />
        </span>
        <input
          aria-label="Search people"
          className="min-h-11 w-full rounded-full border border-[#D6E4F7] bg-white pl-9 pr-4 text-sm text-[#0F172A] outline-none transition placeholder:text-[#94A3B8] focus:border-[#2563EB] focus:ring-4 focus:ring-[#2563EB]/10"
          onChange={(event) => onQueryChange(event.target.value)}
          placeholder={placeholder}
          type="search"
          value={query}
        />
      </div>

      {allPeople.length && hasSearch && visiblePeople.length ? (
        <div className="mt-2 grid gap-1 pr-1">
          {visiblePeople.map((person, index) => (
            <button
              className="flex min-h-9 items-center gap-2.5 rounded-2xl px-2.5 text-left text-sm text-[#0F172A] transition-colors hover:bg-[#F1F5F9]"
              key={person.id}
              onClick={() => onToggle(person.id)}
              type="button"
            >
              <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-[9px] font-semibold ${avatarTone(index)}`}>
                {initials(person.name)}
              </span>
              <span className="min-w-0 flex-1 truncate font-medium">{person.name}</span>
            </button>
          ))}
        </div>
      ) : null}
      {canQuickAdd ? (
        <button
          className="mt-2 flex min-h-10 w-full items-center gap-2.5 rounded-2xl border border-[#BFDBFE] bg-[#EBF2FF] px-3 text-left text-sm font-bold text-[#1D4ED8] transition-colors hover:border-[#2563EB] disabled:cursor-not-allowed disabled:opacity-60"
          disabled={isCreatingPerson}
          onClick={() => {
            void onCreatePerson?.(quickAddName);
          }}
          type="button"
        >
          <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-white text-[#2563EB] ring-1 ring-[#BFDBFE]">
            <Icon name="add" size={13} />
          </span>
          <span className="min-w-0 truncate">
            {isCreatingPerson ? "Adding..." : <>+ Add &ldquo;{quickAddName}&rdquo;</>}
          </span>
        </button>
      ) : null}
    </div>
  );
}

function MinistryTeamSelector({
  allPeople,
  householdMembers,
  onPersonQueryChange,
  onToggleMember,
  onTogglePerson,
  people,
  query,
  selectedMemberIds,
  selectedPersonIds,
}: {
  allPeople: DosAppPerson[];
  householdMembers: DosAppData["householdMembers"];
  onPersonQueryChange: (value: string) => void;
  onToggleMember: (memberId: string) => void;
  onTogglePerson: (personId: string) => void;
  people: DosAppPerson[];
  query: string;
  selectedMemberIds: string[];
  selectedPersonIds: string[];
}) {
  const activeMembers = householdMembers.filter((member) => !["archived", "inactive"].includes(member.status.toLowerCase()));
  const selectedMembers = selectedMemberIds
    .map((memberId) => activeMembers.find((member) => member.id === memberId))
    .filter((member): member is DosAppData["householdMembers"][number] => Boolean(member));
  const selectedPeople = selectedPersonIds
    .map((personId) => allPeople.find((person) => person.id === personId))
    .filter((person): person is DosAppPerson => Boolean(person));
  const hasSearch = query.trim().length > 0;
  const normalizedQuery = query.trim().toLowerCase();
  const visibleMembers = activeMembers.filter((member) => (
    !selectedMemberIds.includes(member.id)
    && hasSearch
    && member.displayName.toLowerCase().includes(normalizedQuery)
  ));
  const visiblePeople = people.filter((person) => !selectedPersonIds.includes(person.id));

  return (
    <div className="grid gap-2">
      {selectedMembers.length || selectedPeople.length ? (
        <div className="flex flex-wrap gap-1.5">
          {selectedMembers.map((member, index) => (
            <button
              aria-label={`Remove ${member.displayName} from ministry team`}
              className="inline-flex h-7 max-w-full items-center gap-1 rounded-full border border-[#F2C94C] bg-[#FFFBEB] pl-1 pr-2 text-[11px] font-semibold text-[#0F172A] transition-colors hover:border-[#D6A300]"
              key={`member-${member.id}`}
              onClick={() => onToggleMember(member.id)}
              type="button"
            >
              <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-[8px] font-bold ${avatarTone(index)}`}>
                {initials(member.displayName)}
              </span>
              <span className="max-w-[9rem] truncate">{member.displayName}</span>
              <span className="ml-0.5 text-[13px] leading-none text-[#A16207]" aria-hidden="true">&times;</span>
            </button>
          ))}
          {selectedPeople.map((person, index) => (
            <button
              aria-label={`Remove ${person.name} from ministry team`}
              className="inline-flex h-7 max-w-full items-center gap-1 rounded-full border border-[#F2C94C] bg-[#FFFBEB] pl-1 pr-2 text-[11px] font-semibold text-[#0F172A] transition-colors hover:border-[#D6A300]"
              key={`person-${person.id}`}
              onClick={() => onTogglePerson(person.id)}
              type="button"
            >
              <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-[8px] font-bold ${avatarTone(index + selectedMembers.length)}`}>
                {initials(person.name)}
              </span>
              <span className="max-w-[9rem] truncate">{person.name}</span>
              <span className="ml-0.5 text-[13px] leading-none text-[#A16207]" aria-hidden="true">&times;</span>
            </button>
          ))}
        </div>
      ) : null}

      <div className="relative">
        <span className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-[#94A3B8]">
          <Icon name="search" size={14} />
        </span>
        <input
          aria-label="Search ministry team"
          className="min-h-11 w-full rounded-full border border-[#D6E4F7] bg-white pl-9 pr-4 text-sm text-[#0F172A] outline-none transition placeholder:text-[#94A3B8] focus:border-[#2563EB] focus:ring-4 focus:ring-[#2563EB]/10"
          onChange={(event) => onPersonQueryChange(event.target.value)}
          placeholder="Search team or field"
          type="search"
          value={query}
        />
      </div>

      {hasSearch && (visibleMembers.length || visiblePeople.length) ? (
        <div className="mt-2 grid gap-1 pr-1">
          {visibleMembers.map((member, index) => (
            <button
              className="flex min-h-9 items-center gap-2.5 rounded-2xl px-2.5 text-left text-sm text-[#0F172A] transition-colors hover:bg-[#F1F5F9]"
              key={member.id}
              onClick={() => onToggleMember(member.id)}
              type="button"
            >
              <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-[9px] font-semibold ${avatarTone(index)}`}>
                {initials(member.displayName)}
              </span>
              <span className="min-w-0 flex-1 truncate font-medium">{member.displayName}</span>
              <span className="rounded-full bg-[#FFFBEB] px-2 py-0.5 text-[10px] font-bold text-[#A16207]">Team</span>
            </button>
          ))}
          {visiblePeople.map((person, index) => (
            <button
              className="flex min-h-9 items-center gap-2.5 rounded-2xl px-2.5 text-left text-sm text-[#0F172A] transition-colors hover:bg-[#F1F5F9]"
              key={person.id}
              onClick={() => onTogglePerson(person.id)}
              type="button"
            >
              <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-[9px] font-semibold ${avatarTone(index + visibleMembers.length)}`}>
                {initials(person.name)}
              </span>
              <span className="min-w-0 flex-1 truncate font-medium">{person.name}</span>
              <span className="rounded-full bg-[#F8FAFC] px-2 py-0.5 text-[10px] font-bold text-[#64748B]">Field</span>
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

function SupportingAttendeeSelector({
  allPeople,
  disabledPersonIds,
  onQueryChange,
  onSubRoleChange,
  onToggle,
  people,
  query,
  selectedPersonIds,
  subRoles,
}: {
  allPeople: DosAppPerson[];
  disabledPersonIds: string[];
  onQueryChange: (value: string) => void;
  onSubRoleChange: (personId: string, value: DosSupportingAttendeeSubRole | "") => void;
  onToggle: (personId: string) => void;
  people: DosAppPerson[];
  query: string;
  selectedPersonIds: string[];
  subRoles: Record<string, DosSupportingAttendeeSubRole | "">;
}) {
  const selectedPeople = selectedPersonIds
    .map((personId) => allPeople.find((person) => person.id === personId))
    .filter((person): person is DosAppPerson => Boolean(person));

  return (
    <div className="grid gap-3">
      <MeetingPeopleSelector
        allPeople={allPeople}
        disabledPersonIds={disabledPersonIds}
        onQueryChange={onQueryChange}
        onToggle={onToggle}
        people={people}
        placeholder="Search supporting attendees"
        query={query}
        removeLabel="from supporting attendees"
        selectedPersonIds={selectedPersonIds}
      />
      {selectedPeople.length ? (
        <div className="grid gap-2">
          {selectedPeople.map((person) => (
            <label className="grid gap-1.5 rounded-[18px] border border-[#EAF2FF] bg-[#F8FAFC] p-2.5" key={person.id}>
              <span className="text-xs font-bold text-[#0F172A]">{person.name}</span>
              <select
                className="min-h-9 rounded-2xl border border-[#D6E4F7] bg-white px-3 text-xs font-bold text-[#475569] outline-none transition focus:border-[#2563EB] focus:ring-4 focus:ring-[#2563EB]/10"
                onChange={(event) => onSubRoleChange(person.id, event.target.value as DosSupportingAttendeeSubRole | "")}
                value={subRoles[person.id] ?? ""}
              >
                {supportingAttendeeSubRoleOptions.map((option) => (
                  <option key={option.value || "none"} value={option.value}>{option.label}</option>
                ))}
              </select>
            </label>
          ))}
        </div>
      ) : null}
    </div>
  );
}

function MeetingCaptureNotes({
  defaultValue,
  label = "Notes",
  showLabel = true,
}: {
  defaultValue?: string | null;
  label?: string;
  showLabel?: boolean;
}) {
  return (
    <DosFormField label={showLabel ? label : undefined}>
      <VoiceTextarea aria-label={label} className={`${FieldTextareaClass(showLabel)} min-h-24`} defaultValue={defaultValue ?? ""} name="notes" />
    </DosFormField>
  );
}

function TableRolePicker({
  onChange,
  value,
}: {
  onChange: (value: DosAppTableRole) => void;
  value: DosAppTableRole;
}) {
  return (
    <>
      <input name="table_role" type="hidden" value={value} />
      <CompactOptionSelect
        label="What best describes your role at this table?"
        onChange={(nextValue) => onChange(normalizeTableRole(nextValue))}
        options={tableRoleOptions}
        value={value}
      />
    </>
  );
}

