function PrayerPartnerSelectField({
  defaultValue,
  label,
  name,
  onChange,
  options,
}: {
  defaultValue?: string;
  label: string;
  name: string;
  onChange?: (value: string) => void;
  options: ReadonlyArray<{ helper?: string; label: string; value: string }>;
}) {
  const fallbackValue = options[0]?.value ?? "";
  const [value, setValue] = useState(defaultValue ?? fallbackValue);
  const selectedValue = options.some((option) => option.value === value) ? value : fallbackValue;

  useEffect(() => {
    setValue(defaultValue ?? fallbackValue);
  }, [defaultValue, fallbackValue]);

  return (
    <>
      <input name={name} type="hidden" value={selectedValue} />
      <CompactOptionSelect
        label={label}
        onChange={(nextValue) => {
          setValue(nextValue);
          onChange?.(nextValue);
        }}
        options={options}
        value={selectedValue}
      />
    </>
  );
}

function prayerPartnerOptionLabel(options: ReadonlyArray<{ label: string; value: string }>, value: string | null | undefined) {
  return options.find((option) => option.value === value)?.label ?? statusLabel(value);
}

function prayerPartnerStatusLabel(value: string | null | undefined) {
  const normalizedStatus = normalizePrayerPartnerStatus(value ?? "");
  const option = prayerPartnerStatusOptions.find((item) => item.value === normalizedStatus);

  return option?.label ?? "Pending Review";
}

function normalizePrayerPartnerRelationshipContext(value: string | null | undefined): RelationshipContextValue {
  const normalized = normalizeText(value).toLowerCase().replace(/[\s-]+/g, "_");
  const option = prayerPartnerRelationshipContextOptions.find((item) => item.value === normalized);

  return option?.value ?? "other";
}

function prayerPartnerHowJoinedLabel(value: string | null | undefined) {
  return prayerPartnerOptionLabel(prayerPartnerHowHeardOptions, value || "other");
}

function prayerPartnerTeamOptions(householdMembers: DosAppHouseholdMember[]) {
  const memberOptions = householdMembers
    .filter((member) => {
      const relationship = normalizeText(member.relationship).toLowerCase();

      return member.status !== "archived" && (relationship === "owner" || relationship === "spouse");
    })
    .sort((first, second) => {
      const order = (member: DosAppHouseholdMember) => normalizeText(member.relationship).toLowerCase() === "owner" ? 0 : 1;

      return order(first) - order(second) || first.displayName.localeCompare(second.displayName);
    })
    .map((member) => ({
      helper: "Personal",
      label: member.displayName,
      value: `member:${member.id}`,
    }));

  return [{ ...prayerPartnerDefaultTeamOption, helper: "Shared" }, ...memberOptions] as ReadonlyArray<{ helper?: string; label: string; value: string }>;
}

function prayerPartnerTeamLabel(value: string | null | undefined, householdMembers: DosAppHouseholdMember[]) {
  return prayerPartnerOptionLabel(prayerPartnerTeamOptions(householdMembers), value || prayerPartnerDefaultTeamOption.value);
}

function prayerPartnerTeamHelper(value: string | null | undefined, householdMembers: DosAppHouseholdMember[]) {
  const selectedValue = value || prayerPartnerDefaultTeamOption.value;

  if (selectedValue === prayerPartnerDefaultTeamOption.value) {
    return "Household / Family: shared prayer partner for this household. Ryan and Brooke can both see it. Counts once on the family public profile.";
  }

  const label = prayerPartnerTeamLabel(selectedValue, householdMembers);
  const firstName = label.split(/\s+/).filter(Boolean)[0] || label;

  return `${label}: personal prayer partner for ${firstName}.`;
}

function PrayerTeamHelperText({
  householdMembers,
  value,
}: {
  householdMembers: DosAppHouseholdMember[];
  value: string | null | undefined;
}) {
  return (
    <p className="mt-2 text-xs font-medium leading-5 text-[#64748B]">
      {prayerPartnerTeamHelper(value, householdMembers)}
    </p>
  );
}

function mapDosPrayerPartnerToLocal(partner: DosAppPrayerPartner): LocalPrayerPartner {
  const relationshipContext = normalizePrayerPartnerRelationshipContext(partner.relationshipContext);

  return {
    city: partner.city,
    email: partner.email,
    fieldPersonId: partner.fieldPersonId,
    howHeard: partner.howHeard ?? "other",
    id: partner.id,
    lastContacted: partner.updatedAt || partner.joinedAt ? formatRelativeDate(partner.updatedAt ?? partner.joinedAt) : "New",
    name: partner.name,
    notes: partner.notes ?? "",
    phone: partner.phone,
    prayerTeam: partner.prayerTeam || prayerPartnerDefaultTeamOption.value,
    relationship: relationshipContextLabel(relationshipContext),
    relationshipContext,
    source: partner.source,
    state: partner.state,
    status: prayerPartnerStatusLabel(partner.status),
  };
}

function isPersistedUuid(value: string) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
}

function normalizePrayerPartnerStatus(value: string) {
  const normalizedValue = normalizeText(value).toLowerCase();

  if (normalizedValue === "inactive") {
    return "paused";
  }

  if (normalizedValue === "active" || normalizedValue === "archived" || normalizedValue === "declined" || normalizedValue === "paused" || normalizedValue === "pending") {
    return normalizedValue;
  }

  return "pending";
}

function upsertById<T extends { id: string }>(rows: T[], nextRow: T) {
  const withoutExisting = rows.filter((row) => row.id !== nextRow.id);

  return [nextRow, ...withoutExisting];
}

function mergeRowsById<T extends { id: string }>(preferredRows: T[], fallbackRows: T[]) {
  const seen = new Set<string>();
  const merged: T[] = [];

  [...preferredRows, ...fallbackRows].forEach((row) => {
    if (seen.has(row.id)) {
      return;
    }

    seen.add(row.id);
    merged.push(row);
  });

  return merged;
}

function prayerRequestVisibilityDisplay(visibility: DosAppPrayerRequest["visibility"]) {
  if (visibility === "public_profile") {
    return "Public Profile";
  }

  if (visibility === "organization") {
    return "Organization";
  }

  if (visibility === "group_leaders") {
    return "Group Leaders";
  }

  if (visibility === "group_members") {
    return "Group Members";
  }

  return "Private";
}

function prayerRequestStatusDisplay(status: DosAppPrayerRequest["status"]) {
  if (status === "answered") {
    return "Answered";
  }

  if (status === "archived") {
    return "Archived";
  }

  return "Active";
}

function prayerRequestSharedWith(request: Pick<DosAppPrayerRequest, "personTags" | "visibility">) {
  if (request.personTags.length > 0) {
    const visibleTags = request.personTags.slice(0, 2).join(", ");
    const hiddenCount = request.personTags.length - 2;

    return hiddenCount > 0 ? `${visibleTags} +${hiddenCount}` : visibleTags;
  }

  return prayerRequestVisibilityDisplay(request.visibility);
}

function mapDosPrayerRequestToLocal(request: DosAppPrayerRequest): LocalPrayerRequest {
  return {
    action: "View",
    answered: request.answeredAt ? formatDate(request.answeredAt) : "—",
    category: request.category ?? "Other",
    created: formatDate(request.createdAt),
    id: request.id,
    personTags: request.personTags,
    request: request.request,
    sharedWith: prayerRequestSharedWith(request),
    status: prayerRequestStatusDisplay(request.status),
    title: request.title,
    view: request.status === "answered" ? "answered" : "praying",
    visibility: request.visibility,
  };
}

function isPrayerRequestActive(request: DosAppPrayerRequest) {
  return request.status !== "answered" && request.status !== "archived";
}

function isPrayerRequestHighPriority(request: DosAppPrayerRequest) {
  return request.priority === "high" || request.priority === "urgent";
}

function isPrayerRequestFollowUpDue(request: DosAppPrayerRequest) {
  if (!request.followUpAt || !isPrayerRequestActive(request)) {
    return false;
  }

  return dateSortValue(request.followUpAt) <= Date.now();
}

function prayerRequestPersonName(request: DosAppPrayerRequest, personById: Map<string, DosAppPerson>) {
  const directPerson = request.fieldPersonId ? personById.get(request.fieldPersonId) : null;

  if (directPerson) {
    return directPerson.name;
  }

  const linkedPerson = request.linkedPersonIds.map((personId) => personById.get(personId)).find(Boolean);

  return linkedPerson?.name ?? null;
}

function prayerRequestContextLabel({
  groupById,
  meetingById,
  personById,
  request,
}: {
  groupById: Map<string, DosAppGroup>;
  meetingById: Map<string, DosAppMeeting>;
  personById: Map<string, DosAppPerson>;
  request: DosAppPrayerRequest;
}) {
  if (request.groupId) {
    const group = groupById.get(request.groupId);

    return group ? `Group · ${group.name}` : "Group prayer";
  }

  const personName = prayerRequestPersonName(request, personById);

  if (personName) {
    return `Person · ${personName}`;
  }

  if (request.meetingId) {
    const meeting = meetingById.get(request.meetingId);

    return meeting ? `Table · ${meetingActivityTitle(meeting)}` : "Table prayer";
  }

  return "Manual";
}

function prayerRequestTabMatches(request: DosAppPrayerRequest, tab: PrayerWorkspaceTab) {
  if (tab === "answered_recently") {
    return request.status === "answered";
  }

  if (!isPrayerRequestActive(request)) {
    return false;
  }

  if (tab === "high_priority") {
    return isPrayerRequestHighPriority(request);
  }

  if (tab === "needs_follow_up") {
    return Boolean(request.followUpAt);
  }

  if (tab === "group_prayers") {
    return Boolean(request.groupId);
  }

  if (tab === "person_prayers") {
    return Boolean(request.fieldPersonId || request.linkedPersonIds.length);
  }

  return true;
}

function prayerRequestHubEmptyCopy(tab: PrayerWorkspaceTab) {
  if (tab === "answered_recently") {
    return { text: "Answered prayer will appear here.", title: "No answered prayer yet." };
  }

  if (tab === "high_priority") {
    return { text: "Requests marked high or urgent will appear here.", title: "No high priority requests." };
  }

  if (tab === "needs_follow_up") {
    return { text: "Requests with a follow-up date will appear here.", title: "No follow-up requests." };
  }

  if (tab === "group_prayers") {
    return { text: "Group prayer requests will appear after they are added from a group.", title: "No group prayers yet." };
  }

  if (tab === "person_prayers") {
    return { text: "Person-linked prayer requests will appear here.", title: "No person prayers yet." };
  }

  return { text: "Add a prayer request or log prayer from a Table to begin.", title: "No prayer requests yet." };
}

function prayerRequestTabLabel(tab: PrayerWorkspaceTab) {
  return prayerWorkspaceTabs.find((item) => item.value === tab)?.label ?? "Prayer";
}

function answerDateInputValue(value: string | null | undefined) {
  if (!value) {
    return new Date().toISOString().slice(0, 10);
  }

  return value.slice(0, 10);
}

type PrayerRequestAudienceOption = {
  helper?: string;
  label: string;
  linkedPersonId?: string;
  tag: string;
  value: string;
};

const prayerAudienceGeneralValue = "audience:household-general";
const prayerAudienceFamilyValue = "audience:family";
const prayerAudienceChildrenValue = "audience:children";

function normalizePrayerAudienceTag(value: string) {
  const normalized = normalizeText(value);
  const key = normalized.toLowerCase();

  if (!normalized) {
    return "";
  }

  if (["family/household", "general", "household", "household/general", "household / general"].includes(key)) {
    return "Household / General";
  }

  if (["child", "children", "kids"].includes(key)) {
    return "Children";
  }

  return normalized;
}

function prayerRequestAudienceOptions(householdMembers: DosAppHouseholdMember[]): PrayerRequestAudienceOption[] {
  const options: PrayerRequestAudienceOption[] = [];
  const seenValues = new Set<string>();
  const seenMemberNames = new Set<string>();
  const addOption = (option: PrayerRequestAudienceOption) => {
    if (seenValues.has(option.value)) {
      return;
    }

    seenValues.add(option.value);
    options.push(option);
  };

  addOption({
    helper: "Whole workspace",
    label: "Household / General",
    tag: "Household / General",
    value: prayerAudienceGeneralValue,
  });
  addOption({
    helper: "Shared family covering",
    label: "Family",
    tag: "Family",
    value: prayerAudienceFamilyValue,
  });
  addOption({
    helper: "Children together",
    label: "Children",
    tag: "Children",
    value: prayerAudienceChildrenValue,
  });

  householdMembers.forEach((member) => {
    const displayName = normalizeText(member.displayName);
    const nameKey = displayName.toLowerCase();

    if (!displayName || seenMemberNames.has(nameKey)) {
      return;
    }

    seenMemberNames.add(nameKey);
    addOption({
      helper: member.roleTitle || member.relationship || undefined,
      label: displayName,
      linkedPersonId: member.id,
      tag: displayName,
      value: `member:${member.id}`,
    });
  });

  return options;
}

function prayerRequestAudienceSelectedOptions(selectedValues: string[], householdMembers: DosAppHouseholdMember[]) {
  const options = prayerRequestAudienceOptions(householdMembers);
  const selectedSet = new Set(selectedValues);
  const selectedOptions = options.filter((option) => selectedSet.has(option.value));

  return selectedOptions.length ? selectedOptions : options.slice(0, 1);
}

function prayerRequestAudiencePayload(selectedValues: string[], householdMembers: DosAppHouseholdMember[]) {
  const selectedOptions = prayerRequestAudienceSelectedOptions(selectedValues, householdMembers);

  return {
    linkedPersonIds: Array.from(new Set(selectedOptions.map((option) => option.linkedPersonId).filter((id): id is string => Boolean(id)))),
    personTags: Array.from(new Set(selectedOptions.map((option) => option.tag).filter(Boolean))),
  };
}

function prayerRequestAudienceValuesFromRequest(request: DosAppPrayerRequest, householdMembers: DosAppHouseholdMember[]) {
  const options = prayerRequestAudienceOptions(householdMembers);
  const linkedPersonIds = new Set(request.linkedPersonIds);
  const normalizedTags = new Set(
    request.personTags
      .map(normalizePrayerAudienceTag)
      .filter(Boolean)
      .map((tag) => tag.toLowerCase()),
  );
  const selectedValues = options
    .filter((option) => (
      (option.linkedPersonId && linkedPersonIds.has(option.linkedPersonId))
      || normalizedTags.has(option.tag.toLowerCase())
    ))
    .map((option) => option.value);

  return selectedValues.length ? selectedValues : [prayerAudienceGeneralValue];
}

function PrayerRequestAudiencePicker({
  householdMembers,
  onChange,
  selectedValues,
}: {
  householdMembers: DosAppHouseholdMember[];
  onChange: (values: string[]) => void;
  selectedValues: string[];
}) {
  const [isOpen, setIsOpen] = useState(false);
  const options = prayerRequestAudienceOptions(householdMembers);
  const selectedOptions = prayerRequestAudienceSelectedOptions(selectedValues, householdMembers);
  const selectedSet = new Set(selectedOptions.map((option) => option.value));
  const summary = selectedOptions.length > 2
    ? `${selectedOptions.slice(0, 2).map((option) => option.label).join(", ")} +${selectedOptions.length - 2}`
    : selectedOptions.map((option) => option.label).join(", ");

  function toggleValue(value: string) {
    const nextValues = selectedSet.has(value)
      ? selectedValues.filter((currentValue) => currentValue !== value)
      : selectedValues.length === 1 && selectedValues[0] === prayerAudienceGeneralValue && value !== prayerAudienceGeneralValue
        ? [value]
      : [...selectedValues, value];

    onChange(nextValues.length ? nextValues : [prayerAudienceGeneralValue]);
  }

  return (
    <div
      className="relative"
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
          setIsOpen(false);
        }
      }}
    >
      <FieldLabel>Who is this request for?</FieldLabel>
      <button
        aria-expanded={isOpen}
        aria-haspopup="listbox"
        className={`mt-2 flex min-h-12 w-full items-center justify-between gap-3 rounded-2xl border bg-white px-4 text-left text-sm transition-colors ${
          isOpen ? "border-[#2563EB] shadow-[0_10px_24px_rgba(37,99,235,0.12)]" : "border-[#E2E8F0] hover:border-[#BFDBFE]"
        }`}
        onClick={() => setIsOpen((current) => !current)}
        type="button"
      >
        <span className="min-w-0 flex-1 truncate font-semibold text-[#0F172A]">{summary || "Household / General"}</span>
        <ChevronRight className={`h-4 w-4 shrink-0 text-[#94A3B8] transition-transform ${isOpen ? "-rotate-90" : "rotate-90"}`} aria-hidden="true" strokeWidth={1.8} />
      </button>
      {isOpen ? (
        <div aria-multiselectable="true" className="absolute left-0 right-0 z-30 mt-1 max-h-72 overflow-y-auto rounded-2xl border border-[#E2E8F0] bg-white p-1.5 shadow-[0_18px_45px_rgba(42,37,29,0.14)]" role="listbox">
          {options.map((option) => {
            const selected = selectedSet.has(option.value);

            return (
              <button
                aria-selected={selected}
                className={`flex min-h-11 w-full items-center justify-between gap-3 rounded-xl px-3 text-left text-sm transition-colors ${
                  selected ? "bg-[#EBF2FF] text-[#1D4ED8]" : "text-[#0F172A] hover:bg-[#F1F5F9]"
                }`}
                key={option.value}
                onClick={() => toggleValue(option.value)}
                role="option"
                type="button"
              >
                <span className="flex min-w-0 flex-1 items-center gap-2">
                  {selected ? (
                    <CheckCircle2 className="h-4 w-4 shrink-0 text-[#2563EB]" aria-hidden="true" strokeWidth={2} />
                  ) : (
                    <Square className="h-4 w-4 shrink-0 text-[#CBD5E1]" aria-hidden="true" strokeWidth={1.8} />
                  )}
                  <span className="min-w-0 truncate font-semibold">{option.label}</span>
                </span>
                {option.helper ? <span className="shrink-0 text-[11px] font-medium text-[#94A3B8]">{option.helper}</span> : null}
              </button>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

function AddPrayerPartnerSheet({
  householdMembers,
  onClose,
  onSubmit,
}: {
  householdMembers: DosAppHouseholdMember[];
  onClose: () => void;
  onSubmit: (partner: DosPrayerPartnerPatch) => Promise<LocalPrayerPartner> | LocalPrayerPartner;
}) {
  const [errorMessage, setErrorMessage] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [prayerTeam, setPrayerTeam] = useState<string>(prayerPartnerDefaultTeamOption.value);
  const teamOptions = prayerPartnerTeamOptions(householdMembers);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const firstName = normalizeText(String(formData.get("first_name") ?? ""));
    const lastName = normalizeText(String(formData.get("last_name") ?? ""));
    const name = [firstName, lastName].filter(Boolean).join(" ");
    const email = normalizeText(String(formData.get("email") ?? ""));
    const phone = normalizeText(String(formData.get("phone") ?? ""));
    const homeAddress = normalizeText(String(formData.get("home_address") ?? ""));
    const city = normalizeText(String(formData.get("city") ?? ""));
    const state = normalizeText(String(formData.get("state") ?? "")).toUpperCase();
    const zip = normalizeText(String(formData.get("zip") ?? ""));
    const church = normalizeText(String(formData.get("church") ?? ""));
    const notes = normalizeText(String(formData.get("notes") ?? ""));
    const relationshipContext = normalizePrayerPartnerRelationshipContext(String(formData.get("relationship_context") ?? ""));
    const prayerTeam = normalizeText(String(formData.get("prayer_team") ?? "")) || prayerPartnerDefaultTeamOption.value;
    const status = normalizeText(String(formData.get("status") ?? "")) || "pending";
    const howHeard = normalizeText(String(formData.get("how_heard") ?? "")) || "invited_by_me";
    const addressLine = [homeAddress, [city, state, zip].filter(Boolean).join(", ")].filter(Boolean).join(" · ");
    const detailNotes = [
      notes,
      church ? `Church: ${church}` : "",
      addressLine ? `Address: ${addressLine}` : "",
    ].filter(Boolean).join(" · ");

    if (!firstName || !lastName) {
      setErrorMessage("First name and last name are required.");
      return;
    }

    if (!email && !phone) {
      setErrorMessage(prayerPartnerContactRequiredMessage);
      return;
    }

    setErrorMessage("");
    setIsSubmitting(true);

    try {
      await onSubmit({
        email,
        howHeard,
        notes: detailNotes,
        phone,
        prayerTeam,
        relationshipContext,
        status,
        name,
      });
      onClose();
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Unable to save prayer partner.");
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <Sheet onClose={onClose} showEyebrow={false} title="Add Prayer Partner">
      <form className="space-y-5" onSubmit={handleSubmit}>
        <DosFormSection icon="people" title="Person">
          <p className="text-xs font-medium leading-5 text-[#64748B]">Prayer-only contacts stay hidden from Field unless added there.</p>
          <DosFormGrid>
            <DosFormField label="First Name">
              <input className={FieldInputClass()} name="first_name" required type="text" />
            </DosFormField>
            <DosFormField label="Last Name">
              <input className={FieldInputClass()} name="last_name" required type="text" />
            </DosFormField>
          </DosFormGrid>
          <DosFormGrid>
            <DosFormField label="Phone">
              <input className={FieldInputClass()} inputMode="tel" name="phone" placeholder="(651) 456-8974" type="tel" />
            </DosFormField>
            <DosFormField label="Email">
              <input className={FieldInputClass()} name="email" placeholder="email@example.com" type="email" />
            </DosFormField>
          </DosFormGrid>
          <PrayerPartnerSelectField label="Relationship Context" name="relationship_context" options={prayerPartnerRelationshipContextOptions} />
        </DosFormSection>
        <DosFormSection icon="home" title="Prayer Partner">
          <DosFormGrid>
            <div>
              <PrayerPartnerSelectField defaultValue={prayerTeam} label="Prayer Team" name="prayer_team" onChange={setPrayerTeam} options={teamOptions} />
              <PrayerTeamHelperText householdMembers={householdMembers} value={prayerTeam} />
            </div>
            <PrayerPartnerSelectField label="How They Joined" name="how_heard" options={prayerPartnerHowHeardOptions} />
          </DosFormGrid>
          <PrayerPartnerSelectField label="Status" name="status" options={prayerPartnerStatusOptions} />
          <details className="group overflow-hidden rounded-[20px] border border-[#D6E4F7] bg-white">
            <summary className="flex min-h-[52px] cursor-pointer list-none items-center justify-between gap-3 px-4 py-3 text-left transition-colors hover:bg-[#F8FBFF] [&::-webkit-details-marker]:hidden">
              <span className="text-sm font-bold text-[#0F172A]">Show additional information</span>
              <ChevronRight className="h-4 w-4 shrink-0 rotate-90 text-[#94A3B8] transition-transform group-open:-rotate-90" aria-hidden="true" strokeWidth={1.9} />
            </summary>
            <div className="grid gap-3 border-t border-[#EAF2FF] bg-white p-3">
              <DosFormField label="Home Address">
                <input className={FieldInputClass()} name="home_address" placeholder="Street address" />
              </DosFormField>
              <div className="grid grid-cols-[minmax(0,1fr)_72px_86px] gap-2 max-[380px]:grid-cols-1">
                <DosFormField label="City">
                  <input className={FieldInputClass()} name="city" />
                </DosFormField>
                <DosFormField label="State">
                  <input className={FieldInputClass()} maxLength={2} name="state" />
                </DosFormField>
                <DosFormField label="ZIP">
                  <input className={FieldInputClass()} inputMode="numeric" name="zip" />
                </DosFormField>
              </div>
              <DosFormField label="Church">
                <input className={FieldInputClass()} name="church" placeholder="Church / community" />
              </DosFormField>
              <DosFormField label="Notes">
                <VoiceTextarea className={`${FieldTextareaClass()} min-h-24`} name="notes" placeholder="What do they help cover?" />
              </DosFormField>
            </div>
          </details>
          <DosFormToggleRow defaultChecked name="email_alerts" title="Email prayer updates" />
        </DosFormSection>
        {errorMessage ? (
          <p className="rounded-2xl border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{errorMessage}</p>
        ) : null}
        <div className="grid gap-2">
          <AppButton disabled={isSubmitting} tone="black" type="submit">{isSubmitting ? "Saving..." : "Add Partner"}</AppButton>
          <AppButton disabled={isSubmitting} onClick={onClose} tone="white">Close</AppButton>
        </div>
      </form>
    </Sheet>
  );
}

function AddPrayerRequestSheet({
  householdMembers,
  onClose,
  onSubmit,
}: {
  householdMembers: DosAppHouseholdMember[];
  onClose: () => void;
  onSubmit: (draft: DosPrayerRequestDraft) => Promise<void>;
}) {
  const [errorMessage, setErrorMessage] = useState("");
  const [audienceValues, setAudienceValues] = useState<string[]>([prayerAudienceGeneralValue]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const title = normalizeText(String(formData.get("title") ?? ""));
    const request = normalizeText(String(formData.get("request") ?? ""));
    const category = normalizeText(String(formData.get("category") ?? "")) || "Other";
    const nextVisibility = normalizeText(String(formData.get("visibility") ?? "")) as DosAppPrayerRequest["visibility"];
    const audience = prayerRequestAudiencePayload(audienceValues, householdMembers);

    if (!title || !request) {
      setErrorMessage("Add a title and request.");
      return;
    }

    setIsSubmitting(true);
    setErrorMessage("");

    try {
      await onSubmit({
        category,
        linkedPersonIds: audience.linkedPersonIds,
        personTags: audience.personTags,
        request,
        title,
        visibility: prayerRequestVisibilityOptions.some((option) => option.value === nextVisibility) ? nextVisibility : "private",
      });
      onClose();
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Unable to save prayer request.");
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <Sheet onClose={onClose} showEyebrow={false} title="Add Prayer Request">
      <form className="space-y-5" onSubmit={handleSubmit}>
        <DosFormSection icon="prayer" title="Prayer Request">
          <DosFormGrid>
            <DosFormField label="Title">
              <input className={FieldInputClass()} name="title" placeholder="What should we pray for?" required type="text" />
            </DosFormField>
            <PrayerPartnerSelectField label="Category" name="category" options={prayerRequestCategoryOptions} />
          </DosFormGrid>
          <DosFormField label="Request">
            <VoiceTextarea className={`${FieldTextareaClass()} min-h-32`} name="request" placeholder="Share enough context for prayer." required />
          </DosFormField>
        </DosFormSection>

        <DosFormSection icon="people" title="Visibility">
          <PrayerPartnerSelectField
            defaultValue="private"
            label="Visibility"
            name="visibility"
            options={prayerRequestVisibilityOptions}
          />
          <p className="rounded-2xl border border-[#D6E4F7] bg-[#F8FBFF] px-3 py-2 text-xs font-semibold leading-5 text-[#475569]">
            Public Profile requests may appear on your missionary page. Private requests stay inside DOS.
          </p>
          <PrayerRequestAudiencePicker householdMembers={householdMembers} onChange={setAudienceValues} selectedValues={audienceValues} />
        </DosFormSection>

        {errorMessage ? (
          <p className="rounded-2xl border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{errorMessage}</p>
        ) : null}
        <div className="grid gap-2">
          <AppButton disabled={isSubmitting} tone="black" type="submit">{isSubmitting ? "Saving..." : "Save Request"}</AppButton>
          <AppButton disabled={isSubmitting} onClick={onClose} tone="white">Close</AppButton>
        </div>
      </form>
    </Sheet>
  );
}

function PrayerRequestDetailSheet({
  householdMembers,
  onClose,
  onDelete,
  onSave,
  request,
}: {
  householdMembers: DosAppHouseholdMember[];
  onClose: () => void;
  onDelete?: (id: string) => Promise<unknown> | unknown;
  onSave: (id: string, patch: DosPrayerRequestPatch) => Promise<DosAppPrayerRequest>;
  request: DosAppPrayerRequest;
}) {
  const [answerTestimony, setAnswerTestimony] = useState(request.answerTestimony ?? "");
  const [answeredDate, setAnsweredDate] = useState(answerDateInputValue(request.answeredAt));
  const [audienceValues, setAudienceValues] = useState<string[]>(() => prayerRequestAudienceValuesFromRequest(request, householdMembers));
  const [category, setCategory] = useState(request.category ?? "Other");
  const [errorMessage, setErrorMessage] = useState("");
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [requestText, setRequestText] = useState(request.request);
  const [status, setStatus] = useState<DosAppPrayerRequest["status"]>(request.status);
  const [title, setTitle] = useState(request.title);
  const [visibility, setVisibility] = useState<DosAppPrayerRequest["visibility"]>(request.visibility);
  const isAnswered = status === "answered";
  const canSave = title.trim() && requestText.trim();

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!canSave) {
      setErrorMessage("Add a title and request.");
      return;
    }

    setIsSubmitting(true);
    setErrorMessage("");

    try {
      const answeredAt = isAnswered
        ? new Date(`${answeredDate || new Date().toISOString().slice(0, 10)}T12:00:00`).toISOString()
        : null;
      const audience = prayerRequestAudiencePayload(audienceValues, householdMembers);

      await onSave(request.id, {
        answerTestimony: isAnswered ? answerTestimony.trim() || null : null,
        answeredAt,
        category,
        fieldPersonId: null,
        linkedPersonIds: audience.linkedPersonIds,
        personTags: audience.personTags,
        request: requestText,
        status,
        title,
        visibility,
      });
      onClose();
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Unable to save prayer request.");
    } finally {
      setIsSubmitting(false);
    }
  }

  async function handleDelete() {
    if (!onDelete) {
      return;
    }

    setIsDeleting(true);
    setErrorMessage("");

    try {
      await onDelete(request.id);
      onClose();
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Unable to delete prayer request.");
    } finally {
      setIsDeleting(false);
    }
  }

  return (
    <Sheet onClose={onClose} showEyebrow={false} title="Prayer Request">
      <form className="space-y-5" onSubmit={handleSubmit}>
        <DosFormSection icon="prayer" title="Request">
          <DosFormGrid>
            <DosFormField label="Title">
              <input className={FieldInputClass()} onChange={(event) => setTitle(event.target.value)} required type="text" value={title} />
            </DosFormField>
            <PrayerPartnerSelectField
              defaultValue={category}
              label="Category"
              name="category"
              onChange={setCategory}
              options={prayerRequestCategoryOptions}
            />
          </DosFormGrid>
          <DosFormField label="Request">
            <VoiceTextarea className={`${FieldTextareaClass()} min-h-32`} onChange={(event) => setRequestText(event.target.value)} required value={requestText} />
          </DosFormField>
        </DosFormSection>

        <DosFormSection icon="people" title="Visibility">
          <DosFormGrid>
            <PrayerPartnerSelectField
              defaultValue={visibility}
              label="Visibility"
              name="visibility"
              onChange={(value) => setVisibility(value as DosAppPrayerRequest["visibility"])}
              options={prayerRequestVisibilityOptions}
            />
            <PrayerPartnerSelectField
              defaultValue={status}
              label="Status"
              name="status"
              onChange={(value) => setStatus(value as DosAppPrayerRequest["status"])}
              options={prayerRequestStatusOptions}
            />
          </DosFormGrid>
          <p className="rounded-2xl border border-[#D6E4F7] bg-[#F8FBFF] px-3 py-2 text-xs font-semibold leading-5 text-[#475569]">
            Public Profile requests may appear on your missionary page. Private requests stay inside DOS.
          </p>
          <PrayerRequestAudiencePicker householdMembers={householdMembers} onChange={setAudienceValues} selectedValues={audienceValues} />
        </DosFormSection>

        {isAnswered ? (
          <DosFormSection icon="fruit" title="Answer">
            <DosFormField label="Answered Date">
              <input className={FieldInputClass()} onChange={(event) => setAnsweredDate(event.target.value)} type="date" value={answeredDate} />
            </DosFormField>
            <DosFormField label="Answer / Testimony">
              <VoiceTextarea className={`${FieldTextareaClass()} min-h-28`} onChange={(event) => setAnswerTestimony(event.target.value)} placeholder="What did God do?" value={answerTestimony} />
            </DosFormField>
          </DosFormSection>
        ) : (
          <AppButton onClick={() => {
            setStatus("answered");
            setAnsweredDate(new Date().toISOString().slice(0, 10));
          }} tone="white">Mark Answered</AppButton>
        )}

        {onDelete ? (
          <DosFormSection icon="settings" title="Cleanup">
            {isConfirmingDelete ? (
              <div className="grid gap-3 rounded-2xl border border-red-200 bg-red-50 p-3">
                <p className="text-sm font-semibold leading-6 text-red-800">
                  Permanently delete this prayer request? This should only be used for duplicates, spam, or test records. This cannot be undone.
                </p>
                <div className="grid gap-2 min-[420px]:grid-cols-2">
                  <button
                    className="min-h-11 rounded-2xl border border-red-700 bg-red-700 px-4 py-2 text-sm font-black text-white transition hover:bg-red-800 disabled:cursor-not-allowed disabled:opacity-60"
                    disabled={isDeleting || isSubmitting}
                    onClick={() => void handleDelete()}
                    type="button"
                  >
                    {isDeleting ? "Deleting..." : "Confirm Delete"}
                  </button>
                  <button
                    className="min-h-11 rounded-2xl border border-red-200 bg-white px-4 py-2 text-sm font-black text-red-700 transition hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-60"
                    disabled={isDeleting}
                    onClick={() => setIsConfirmingDelete(false)}
                    type="button"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            ) : (
              <button
                className="min-h-11 w-full rounded-2xl border border-red-200 bg-white px-4 py-2 text-sm font-black text-red-700 transition hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-60"
                disabled={isDeleting || isSubmitting}
                onClick={() => {
                  setIsConfirmingDelete(true);
                  setErrorMessage("");
                }}
                type="button"
              >
                Delete Request
              </button>
            )}
          </DosFormSection>
        ) : null}

        {errorMessage ? (
          <p className="rounded-2xl border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{errorMessage}</p>
        ) : null}
        <div className="grid gap-2">
          <AppButton disabled={!canSave || isSubmitting} tone="black" type="submit">{isSubmitting ? "Saving..." : "Save Request"}</AppButton>
          <AppButton disabled={isSubmitting} onClick={onClose} tone="white">Close</AppButton>
        </div>
      </form>
    </Sheet>
  );
}

function PrayerPartnerDetailSheet({
  householdMembers,
  onClose,
  onDeletePartner,
  onSavePartner,
  partner,
}: {
  householdMembers: DosAppHouseholdMember[];
  onClose: () => void;
  onDeletePartner?: (partner: LocalPrayerPartner) => Promise<unknown> | unknown;
  onSavePartner: (partner: LocalPrayerPartner, patch: DosPrayerPartnerPatch) => Promise<LocalPrayerPartner> | LocalPrayerPartner;
  partner: LocalPrayerPartner;
}) {
  const [errorMessage, setErrorMessage] = useState("");
  const [isConfirmingArchive, setIsConfirmingArchive] = useState(false);
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [name, setName] = useState(partner.name);
  const [email, setEmail] = useState(partner.email ?? "");
  const [howHeard, setHowHeard] = useState(partner.howHeard || "other");
  const [phone, setPhone] = useState(partner.phone ?? "");
  const [notes, setNotes] = useState(partner.notes ?? "");
  const [prayerTeam, setPrayerTeam] = useState(partner.prayerTeam || prayerPartnerDefaultTeamOption.value);
  const [relationshipContext, setRelationshipContext] = useState<RelationshipContextValue>(partner.relationshipContext);
  const [successMessage, setSuccessMessage] = useState(partner.notice ?? "");
  const [status, setStatus] = useState(normalizePrayerPartnerStatus(partner.status));
  const canSave = name.trim() && (email.trim() || phone.trim());
  const teamOptions = prayerPartnerTeamOptions(householdMembers);

  useEffect(() => {
    setSuccessMessage(partner.notice ?? "");
  }, [partner.id, partner.notice]);

  async function savePartner(nextStatus = status, closeAfterSave = false) {
    if (!name.trim()) {
      setErrorMessage("Name is required.");
      return null;
    }

    if (!email.trim() && !phone.trim()) {
      setErrorMessage(prayerPartnerContactRequiredMessage);
      return null;
    }

    setIsSubmitting(true);
    setErrorMessage("");
    setSuccessMessage("");

    try {
      const savedPartner = await onSavePartner(partner, {
        email: email.trim(),
        howHeard,
        name: name.trim(),
        notes: notes.trim(),
        phone: phone.trim(),
        prayerTeam,
        relationshipContext,
        status: nextStatus,
      });

      setSuccessMessage(nextStatus === "archived" ? "Partner archived." : "Partner saved.");

      if (closeAfterSave) {
        onClose();
      }

      return savedPartner;
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Unable to update prayer partner.");
      return null;
    } finally {
      setIsSubmitting(false);
    }
  }

  async function archivePartner() {
    if (!isConfirmingArchive) {
      setIsConfirmingArchive(true);
      setSuccessMessage("");
      return;
    }

    await savePartner("archived", true);
  }

  async function deletePartner() {
    if (!onDeletePartner) {
      return;
    }

    setIsDeleting(true);
    setErrorMessage("");
    setSuccessMessage("");

    try {
      await onDeletePartner(partner);
      onClose();
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Unable to delete prayer partner.");
    } finally {
      setIsDeleting(false);
    }
  }

  return (
    <Sheet onClose={onClose} showEyebrow={false} title={partner.name}>
      <form className="space-y-5" onSubmit={(event) => {
        event.preventDefault();
        void savePartner();
      }}>
        <DosFormSection icon="people" title="Person">
          <DosFormGrid>
            <DosFormField label="Name">
              <input className={FieldInputClass()} onChange={(event) => setName(event.target.value)} required type="text" value={name} />
            </DosFormField>
            <DosFormField label="Email">
              <input className={FieldInputClass()} onChange={(event) => setEmail(event.target.value)} type="email" value={email} />
            </DosFormField>
          </DosFormGrid>
          <DosFormGrid>
            <DosFormField label="Phone">
              <input className={FieldInputClass()} inputMode="tel" onChange={(event) => setPhone(event.target.value)} type="tel" value={phone} />
            </DosFormField>
            <PrayerPartnerSelectField
              defaultValue={relationshipContext}
              label="Relationship Context"
              name="relationship_context"
              onChange={(value) => setRelationshipContext(normalizePrayerPartnerRelationshipContext(value))}
              options={prayerPartnerRelationshipContextOptions}
            />
          </DosFormGrid>
        </DosFormSection>
        <DosFormSection icon="settings" title="Prayer Partner">
          <DosFormGrid>
            <div>
              <PrayerPartnerSelectField
                defaultValue={prayerTeam}
                label="Prayer Team"
                name="prayer_team"
                onChange={setPrayerTeam}
                options={teamOptions}
              />
              <PrayerTeamHelperText householdMembers={householdMembers} value={prayerTeam} />
            </div>
            <PrayerPartnerSelectField
              defaultValue={howHeard}
              label="How They Joined"
              name="how_heard"
              onChange={setHowHeard}
              options={prayerPartnerHowHeardOptions}
            />
          </DosFormGrid>
          <PrayerPartnerSelectField
            defaultValue={status}
            label="Status"
            name="status"
            onChange={setStatus}
            options={prayerPartnerStatusOptions}
          />
          <DosFormField label="Notes">
            <VoiceTextarea className={`${FieldTextareaClass()} min-h-28`} onChange={(event) => setNotes(event.target.value)} value={notes} />
          </DosFormField>
          <p className="text-xs font-semibold text-[#64748B]">Last updated {partner.lastContacted}</p>
        </DosFormSection>
        {successMessage ? (
          <p className="rounded-2xl border border-emerald-200 bg-emerald-50 px-3 py-2 text-sm text-emerald-700">{successMessage}</p>
        ) : null}
        {errorMessage ? (
          <p className="rounded-2xl border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{errorMessage}</p>
        ) : null}
        <DosFormSection icon="settings" title="Actions">
          <div className="grid gap-2">
            <AppButton disabled={!canSave || isSubmitting} tone="black" type="submit">{isSubmitting ? "Saving..." : "Save Partner"}</AppButton>
            <AppButton disabled={isSubmitting} onClick={archivePartner} tone="white">{isConfirmingArchive ? "Confirm Archive" : "Archive Partner"}</AppButton>
            {onDeletePartner ? (
              isConfirmingDelete ? (
                <div className="grid gap-3 rounded-2xl border border-red-200 bg-red-50 p-3">
                  <p className="text-sm font-semibold leading-6 text-red-800">
                    Permanently delete this prayer partner? This should only be used for duplicates, spam, or test records. This cannot be undone.
                  </p>
                  <div className="grid gap-2 min-[420px]:grid-cols-2">
                    <button
                      className="min-h-11 rounded-2xl border border-red-700 bg-red-700 px-4 py-2 text-sm font-black text-white transition hover:bg-red-800 disabled:cursor-not-allowed disabled:opacity-60"
                      disabled={isDeleting || isSubmitting}
                      onClick={() => void deletePartner()}
                      type="button"
                    >
                      {isDeleting ? "Deleting..." : "Confirm Delete"}
                    </button>
                    <button
                      className="min-h-11 rounded-2xl border border-red-200 bg-white px-4 py-2 text-sm font-black text-red-700 transition hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-60"
                      disabled={isDeleting}
                      onClick={() => setIsConfirmingDelete(false)}
                      type="button"
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              ) : (
                <button
                  className="min-h-11 w-full rounded-2xl border border-red-200 bg-white px-4 py-2 text-sm font-black text-red-700 transition hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-60"
                  disabled={isDeleting || isSubmitting}
                  onClick={() => {
                    setIsConfirmingDelete(true);
                    setIsConfirmingArchive(false);
                    setErrorMessage("");
                    setSuccessMessage("");
                  }}
                  type="button"
                >
                  Delete Partner
                </button>
              )
            ) : null}
            <AppButton disabled={isSubmitting} onClick={onClose} tone="white">Close</AppButton>
          </div>
        </DosFormSection>
      </form>
    </Sheet>
  );
}

function PrayerTeamCountVisibilityToggle({
  checked,
  onChange,
}: {
  checked: boolean;
  onChange: (value: boolean) => Promise<void>;
}) {
  const [errorMessage, setErrorMessage] = useState("");
  const [isSaving, setIsSaving] = useState(false);

  async function handleChange(event: ChangeEvent<HTMLInputElement>) {
    const nextValue = event.target.checked;

    setErrorMessage("");
    setIsSaving(true);

    try {
      await onChange(nextValue);
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Unable to update prayer team count visibility.");
    } finally {
      setIsSaving(false);
    }
  }

  return (
    <div className="grid gap-2">
      <DosFormToggleRow
        checked={checked}
        description="Partner names stay private either way."
        disabled={isSaving}
        name="show_prayer_team_count"
        onChange={handleChange}
        title="Show prayer team count on public profile"
      />
      {errorMessage ? (
        <p className="rounded-2xl border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{errorMessage}</p>
      ) : null}
    </div>
  );
}

function LogPrayerSheet({
  onClose,
  onSubmit,
  prayerRows,
}: {
  onClose: () => void;
  onSubmit: (entry: LocalPrayerLogEntry) => void;
  prayerRows: PrayerDetail[];
}) {
  const defaultPrayerId = prayerRows[0]?.id ?? "";

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const formData = new FormData(event.currentTarget);
    const prayerId = String(formData.get("prayer_id") ?? defaultPrayerId);

    if (!prayerId) {
      return;
    }

    onSubmit({
      id: `local-prayer-log-${Date.now()}`,
      notes: normalizeText(String(formData.get("notes") ?? "")),
      prayedAt: new Date().toISOString(),
      prayerId,
    });
  }

  return (
    <Sheet onClose={onClose} showEyebrow={false} title="Log Prayer">
      <form className="space-y-3" onSubmit={handleSubmit}>
        {prayerRows.length ? (
          <>
            <section className={meetingFormGroupClassName}>
              <div className={meetingFormGroupCardClassName}>
                <p className={meetingFormGroupTitleClassName}>Prayer Log</p>
                <div className="mt-3 grid gap-3">
                  <label className="block">
                    <FieldLabel>Prayer Request</FieldLabel>
                    <select className={FieldInputClass()} defaultValue={defaultPrayerId} name="prayer_id">
                      {prayerRows.map((row) => (
                        <option key={row.id} value={row.id}>{row.personName} · {row.request}</option>
                      ))}
                    </select>
                  </label>
                  <label className="block">
                    <VoiceTextarea aria-label="Notes" className={`${FieldTextareaClass(false)} min-h-24`} name="notes" />
                  </label>
                </div>
              </div>
            </section>
            <div className="grid gap-2">
              <AppButton tone="black" type="submit">Log Prayer</AppButton>
              <AppButton onClick={onClose} tone="white">Close</AppButton>
            </div>
          </>
        ) : (
          <div className="grid gap-3">
            <SectionEmptyState text="Add a prayer request first, then log prayer against it." title="No prayer requests yet." />
            <AppButton onClick={onClose} tone="white">Close</AppButton>
          </div>
        )}
      </form>
    </Sheet>
  );
}

